function progressEvents(){
  if(!state.dailyProgress||typeof state.dailyProgress!=='object'||Array.isArray(state.dailyProgress))state.dailyProgress={};
  if(!state.dailyProgress[day]||typeof state.dailyProgress[day]!=='object')state.dailyProgress[day]={events:{}};
  if(!state.dailyProgress[day].events||typeof state.dailyProgress[day].events!=='object'||Array.isArray(state.dailyProgress[day].events))state.dailyProgress[day].events={};
  return state.dailyProgress[day].events
}
function recordDailyProgress(area,id,units=1,minutes=1){
  const events=progressEvents();if(!events[id])events[id]={area,units,minutes};save()
}
function dailyProgressSummary(){
  const totals={Grammatik:0,Sprechen:0,Schreiben:0,Hören:0,Wortschatz:0};let autoMinutes=0;
  Object.values(progressEvents()).forEach(event=>{if(event&&totals[event.area]!=null)totals[event.area]+=event.units||0;autoMinutes+=event?.minutes||0});
  const targets={Grammatik:+document.querySelector('#caseCount')?.value||5,Sprechen:+document.querySelector('#verbCount')?.value||5,Schreiben:4,Hören:2,Wortschatz:10};
  const percentages=Object.fromEntries(Object.keys(totals).map(name=>[name,Math.min(100,Math.round(totals[name]/targets[name]*100))]));
  return{totals,percentages,autoMinutes}
}
