function currentListening(){const n=Math.floor(new Date(listeningDate.value+'T12:00:00Z').getTime()/86400000);return listeningExercises[((n%listeningExercises.length)+listeningExercises.length)%listeningExercises.length]}
function formatListeningTime(seconds){seconds=Math.max(0,Math.round(seconds));return`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}
function updateListeningTimeline(offset=listeningOffset,moveSlider=true){const item=currentListening();const rate=13*+listeningRate.value;const ratio=item.text.length?offset/item.text.length:0;if(moveSlider&&!listeningDragging)listeningSeek.value=Math.round(ratio*1000);document.querySelector('#listeningCurrentTime').textContent=formatListeningTime(offset/rate);document.querySelector('#listeningTotalTime').textContent=formatListeningTime(item.text.length/rate)}
