function stopListening(){listeningRun++;stopListeningTimer();if(nativeTts)nativeTts.stop().catch(()=>{});if('speechSynthesis'in window)window.speechSynthesis.cancel();listeningUtterance=null;listeningOffset=0;listeningPaused=false;document.querySelector('#pauseListening').textContent='⏸ Pause';updateListeningTimeline(0);document.querySelector('#listeningStatus').textContent='Wiedergabe gestoppt'}
function renderListening(){if(!listeningExercises.length)return;stopListening();const item=currentListening();const saved=listeningState[listeningDate.value]||{answers:[]};document.querySelector('#listeningTopic').textContent=`TAGESÜBUNG ${item.id} VON ${listeningExercises.length}`;document.querySelector('#listeningTitle').textContent=item.title;const box=document.querySelector('#listeningQuestions');box.innerHTML=item.questions.map((q,i)=>`<article class="listening-question" data-question="${i}"><span>FRAGE ${i+1}</span><h3>${q.q}</h3>${q.options.map((o,j)=>`<button type="button" class="listening-option${saved.answers?.[i]===j?' selected':''}" data-answer="${j}">${o}</button>`).join('')}<small class="listening-explanation"></small></article>`).join('');box.querySelectorAll('.listening-option').forEach(btn=>btn.addEventListener('click',()=>{const card=btn.closest('.listening-question');card.querySelectorAll('.listening-option').forEach(x=>x.classList.remove('selected','correct','wrong'));btn.classList.add('selected');const q=+card.dataset.question;if(!listeningState[listeningDate.value])listeningState[listeningDate.value]={answers:[]};listeningState[listeningDate.value].answers[q]=+btn.dataset.answer;localStorage.setItem(LISTENING_KEY,JSON.stringify(listeningState));document.querySelector('#listeningScore').textContent='Noch nicht geprüft';card.querySelector('.listening-explanation').textContent=''}));const transcript=document.querySelector('#listeningTranscript');transcript.hidden=true;transcript.querySelector('p').textContent=item.text;document.querySelector('#showTranscript').textContent='Transkript anzeigen';document.querySelector('#listeningScore').textContent=saved.score!=null?`${saved.score} von 2 richtig`:'Noch nicht geprüft';updateListeningTimeline(0);document.querySelector('#listeningStatus').textContent='Bereit zum Anhören'}
function speakListening(offset=0){const item=currentListening();if(!('speechSynthesis'in window)){document.querySelector('#listeningSupport').hidden=false;return}listeningRun++;const run=listeningRun;stopListeningTimer();window.speechSynthesis.cancel();listeningOffset=Math.max(0,Math.min(offset,item.text.length));while(listeningOffset>0&&item.text[listeningOffset-1]!==' ')listeningOffset--;const base=listeningOffset;listeningDragging=false;updateListeningTimeline(base);const utterance=new SpeechSynthesisUtterance(item.text.slice(base));listeningUtterance=utterance;utterance.lang='de-DE';utterance.rate=+listeningRate.value;const selected=germanVoices.find(v=>v.voiceURI===listeningVoice.value)||germanVoices[0];if(selected)utterance.voice=selected;utterance.onstart=()=>{if(run!==listeningRun)return;listeningPaused=false;startListeningTimer(run);document.querySelector('#pauseListening').textContent='⏸ Pause';document.querySelector('#listeningStatus').textContent=`Wiedergabe läuft${selected?' · '+selected.name:''} …`};utterance.onend=()=>{if(run!==listeningRun)return;stopListeningTimer();listeningOffset=item.text.length;updateListeningTimeline();listeningUtterance=null;document.querySelector('#listeningStatus').textContent='Text beendet – beantworte jetzt die Fragen'};utterance.onerror=()=>{if(run===listeningRun){stopListeningTimer();document.querySelector('#listeningStatus').textContent='Die Wiedergabe konnte nicht gestartet werden.'}};setTimeout(()=>{if(run===listeningRun)window.speechSynthesis.speak(utterance)},250)}
function seekListening(seconds){const item=currentListening();const visibleOffset=item.text.length*(+listeningSeek.value/1000);const charsPerSecond=13*+listeningRate.value;const target=Math.max(0,Math.min(item.text.length,visibleOffset+seconds*charsPerSecond));listeningSeek.value=Math.round(target/item.text.length*1000);speakListening(target);document.querySelector('#listeningStatus').textContent=seconds<0?'5 Sekunden zurückgesprungen':'5 Sekunden vorgesprungen'}
