function dailyCorrections(){const n=Math.floor(new Date(correctionDate.value+'T12:00:00Z').getTime()/86400000);const start=(((n%corrections.length)+corrections.length)%corrections.length);return Array.from({length:2},(_,i)=>corrections[(start*2+i)%corrections.length])}
