function syncTodayProgressFromSavedWork(){
  const events=progressEvents(),add=(area,id,units,minutes)=>{if(!events[id])events[id]={area,units,minutes}};
  Object.entries(articleState[day]||{}).forEach(([noun,answer])=>{if(answer)add('Wortschatz',`article:${day}:${noun}`,1,1)});
  Object.entries(verbState).filter(([key])=>key.startsWith(day+'-')).forEach(([key,entries])=>Object.entries(entries||{}).forEach(([verb,forms])=>{if(Array.isArray(forms)&&forms.every(value=>String(value||'').trim()))add('Sprechen',`verb:${key}:${verb}`,1,3)}));
  const listening=listeningState[day];(listening?.answers||[]).forEach((answer,index)=>{if(answer!=null)add('Hören',`listening:${day}:${currentListening().id}:${index}`,1,5)});
  Object.entries(caseState).filter(([key])=>key.startsWith(day+'|')).forEach(([key,entries])=>Object.entries(entries||{}).forEach(([id,entry])=>{if(entry?.checked&&entry?.selected)add('Grammatik',`case:${day}:${key.split('|').slice(1).join('|')}:${id}`,1,2)}));
  Object.entries(correctionState[day]||{}).forEach(([id,entry])=>{if(entry?.rating)add('Schreiben',`correction:${day}:${id}`,1,5)});
  Object.entries(labState[day]||{}).forEach(([type,entries])=>Object.entries(entries||{}).forEach(([index,entry])=>{if(entry?.checked||(type==='connectors'&&entry?.revealed&&entry?.text)){const area=type==='endings'||type==='connectors'?'Grammatik':'Wortschatz';add(area,`lab:${day}:${type}:${index}`,1,2)}}));
  const written=writing[day];if(written?.text?.trim())add('Schreiben',`writing:${day}`,2,10);if(written?.comparisonPairs?.some(pair=>(pair.originalHtml||pair.correctedHtml||'').replace(/<[^>]*>/g,'').trim()))add('Schreiben',`writing-pairs:${day}`,2,10);if((written?.correctedHtml||'').replace(/<[^>]*>/g,'').trim())add('Schreiben',`writing-corrected:${day}`,1,5);
  (vocabularyState[day]||[]).forEach((entry,index)=>{if(entry?.word?.trim()&&entry?.meaning?.trim())add('Wortschatz',`vocabulary:${day}:${index}`,1,1)});
  localStorage.setItem(KEY,JSON.stringify(state));render()
}
syncTodayProgressFromSavedWork();
